		LiveS3TargetSHA256:                  strings.Repeat("8", 64),
		LiveS3Credential:                    oci.SecretVersionReference{SecretOCID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.alpha", VersionNumber: 3},
		ReplicationListenAddress:            "10.0.0.11:7000",
