	if _, err := controller.ApplyDesired(t.Context(), desired); err != nil {
		t.Fatal(err)
	}
	sessionID := "00000000000000000000000004"
	accepted, err := controller.handleSession(t.Context(), signedHostRequest(t, hostKey, "session", sessionID, 0,
