func (c *Controller) RequestManagedDrain(ctx context.Context, command ManagedDrainCommand) error {
	if err := c.guard(ctx, command.Epoch); err != nil {
		return err
	}
	registration, _, found, err := c.readRegistration(ctx, command.Node)
	if err != nil || !found {
		return errors.Join(errors.New("managed drain host registration is unavailable"), err)
	}
	if !slices.Contains(registration.Roles, command.Role) || registration.ManagedPlacement == nil ||
		c.managedVerifier == nil {
		return errors.New("managed drain requires an admitted placement host")
	}
	if err := c.managedVerifier.VerifyManagedRegistration(ctx, registration); err != nil {
		return err
	}
	desired, _, found, err := c.readDesired(ctx, command.Node, command.Role)
	if err != nil || !found || !command.matchesDesired(desired, registration) {
		return errors.Join(errors.New("managed drain command differs from current signed desired"), err)
	}
	key := managedDrainKey(c.cell, command.Node, command.Role)
	var prior ManagedDrainCommand
	_, exists, err := c.get(ctx, key, &prior)
	if err != nil {
		return err
	}
	if exists {
		if !sameManagedDrainOperation(prior, command) {
			return memberstatus.ErrOperationConflict
		}
		return nil
	}
	session, _, found, err := c.sessionSnapshot(ctx, sessionKey(c.cell, command.Node))
	if err != nil || !found || session.RegistrationGeneration != registration.Generation ||
		!time.Now().Before(session.ExpiresAt) {
		return errors.Join(errors.New("managed drain host session is unavailable"), err)
	}
	report, _, found, err := c.reportSnapshot(ctx, reportKey(c.cell, command.Node, command.Role))
	if err != nil || !found || report.SessionID != session.SessionID || report.Epoch != session.Epoch ||
		report.Generation != desired.Generation || report.Digest != desired.Digest ||
		report.State != "running" || time.Since(report.ObservedAt) >= ReportMaxAge ||
		report.ObservedAt.After(time.Now().Add(maxClockSkew)) ||
		validateManagedReportForDesired(report, desired) != nil || report.Managed.ServingProof == nil ||
		report.Managed.ProcessPID != command.ExpectedProcess.PID ||
		report.Managed.ProcessBootID != command.ExpectedProcess.StartNonce ||
		report.Managed.ServingProof.Replication.LocalSourceSequence != command.SourceSequence ||
		memberstatus.VerifyReportedServing(*report.Managed.ServingProof, drainIdentity(command), command.Survivor) != nil {
		return errors.Join(errors.New("managed drain lacks a current native serving report"), err)
	}
	for range 8 {
		var old ManagedDrainCommand
		revision, found, err := c.get(ctx, key, &old)
		if err != nil {
			return err
		}
		if found {
			if !sameManagedDrainOperation(old, command) {
				return memberstatus.ErrOperationConflict
			}
			return nil
		}
		if err := c.guard(ctx, command.Epoch); err != nil {
			return err
		}
		if _, err := c.cas(ctx, key, command, revision); err == nil {
			return nil
		} else if !casConflict(err) {
			return err
		}
	}
	return errors.New("managed drain command contention")
}

func (c *Controller) serveManagedDrainCommand(ctx context.Context, req request, registration Registration) (any, error) {
	var query managedDrainQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(registration.Roles, query.Role) {
		return nil, errors.New("managed drain role is not registered")
	}
	var command ManagedDrainCommand
	_, found, err := c.get(ctx, managedDrainKey(c.cell, req.Node, query.Role), &command)
	if err != nil || !found {
		return managedDrainReply{}, err
	}
	desired, _, current, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil || !current || !command.matchesDesired(desired, registration) {
		return nil, errors.Join(errors.New("managed drain command is no longer current"), err)
	}
	if c.managedVerifier == nil {
		return nil, errors.New("managed drain verifier is unavailable")
	}
	if err := c.managedVerifier.VerifyManagedRegistration(ctx, registration); err != nil {
		return nil, err
	}
	return managedDrainReply{Command: &command}, nil
}

func (c *Controller) authorize(ctx context.Context, req request) (Registration, session, error) {
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return Registration{}, session{}, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return Registration{}, session{}, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return Registration{}, session{}, err
		}
		s, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
			return Registration{}, session{}, errors.New("host session is not current")
		}
		if _, err := c.cas(ctx, stateKey, s, revision); err == nil {
			return r, s, nil
		} else if !casConflict(err) {
			return Registration{}, session{}, fmt.Errorf("host session changed: %w", err)
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return Registration{}, session{}, err
		}
	}
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return Registration{}, session{}, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return Registration{}, session{}, err
	}
	if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
		return Registration{}, session{}, err
	}
	s, _, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
		return Registration{}, session{}, errors.New("host session is not current")
	}
	return Registration{}, session{}, errSessionContention
}

func (c *Controller) handleAuthorized(ctx context.Context, req request) (payload any, resultErr error) {
	r, s, err := c.authorize(ctx, req)
	if err != nil {
		return nil, err
	}
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	requireActive := req.Operation == "material" || req.Operation == "container-material" || req.Operation == "registry-admission" || req.Operation == "function-material"
	if req.Operation == "runtime-effect" {
		var operation struct {
			Action string `json:"action"`
		}
		if err := json.Unmarshal(req.Payload, &operation); err != nil {
			return nil, err
		}
		requireActive = operation.Action != "close"
	}
	defer func() {
		if resultErr != nil {
			return
		}
		if err := c.recheckReplyAuthority(ctx, epoch, req, r, requireActive); err != nil {
			payload, resultErr = nil, err
		}
	}()
	switch req.Operation {
	case "desired":
		registration, registrationRevision, exists, err := c.readRegistration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		if !exists || !sameJSON(registration, r) || registration.Generation != s.RegistrationGeneration {
			return nil, errors.New("host registration changed during desired request")
		}
		var query struct {
			Role string `json:"role"`
		}
		if err := decodeStrict(req.Payload, &query); err != nil {
			return nil, err
		}
		if !slices.Contains(r.Roles, query.Role) {
			return nil, errors.New("role is not registered")
		}
		desired, revision, exists, err := c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists {
			return desiredReply{Registration: &registration, RegistrationRevision: registrationRevision}, nil
		}
		return desiredReply{Desired: &desired, Revision: revision, Registration: &registration, RegistrationRevision: registrationRevision}, nil
	case "artifact":
		return c.serveArtifact(ctx, req, r)
	case "material":
		return c.serveMaterial(ctx, req, r, s)
	case "function-material":
		return c.serveFunctionMaterial(ctx, req, r, s)
	case "volume-init":
		return c.serveVolumeInit(ctx, req, r, s)
	case "runtime-effect":
		return c.serveRuntimeEffect(ctx, req, r, s)
	case "container-material":
		return c.serveContainerMaterial(ctx, req, r, s)
	case "registry-admission":
		return c.serveRegistryAdmission(ctx, req, r, s)
	case "drain-command":
		return c.serveManagedDrainCommand(ctx, req, r)
	case "drain-result":
		return c.storeManagedDrainResult(ctx, req, r)
	case "backup-command":
		return c.serveManagedBackupCommand(ctx, req, r)
	case "backup-result":
		return c.storeManagedBackupResult(ctx, req, r)
	case "cycle":
		return c.serveCycle(ctx, req, r, s)
	case "report":
		return c.storeReport(ctx, req, r, s)
	case "load":
		return c.storeLoad(ctx, req, r)
	case "rollout", "rollout-binary":
		return c.serveRollout(ctx, req, r)
	case "netbird", "netbird-binary":
		return c.serveNetBird(ctx, req, r)
	case "terrabase-peer":
		return c.serveTerraBasePeer(ctx, req, r)
	case "terrabase-format":
		return c.serveTerraBaseFormat(ctx, req, r)
	case "role-identity":
		return c.serveRoleIdentity(ctx, req, r)
	}
	return nil, errors.New("unknown host operation")
}

func (c *Controller) storeReport(ctx context.Context, req request, r Registration, s session) (any, error) {
	var report Report
	if err := decodeStrict(req.Payload, &report); err != nil {
		return nil, err
	}
	if report.Cell != c.cell || report.Node != req.Node || report.Environment != r.Environment || !slices.Contains(r.Roles, report.Role) || report.SessionID != s.SessionID || report.Epoch != s.Epoch ||
		report.ObservedAt.Before(req.IssuedAt.Add(-30*time.Second)) || report.ObservedAt.After(time.Now().Add(maxClockSkew)) || report.ObservedAt.IsZero() || len(report.Error) > 1024 || len(report.State) > 64 {
		return nil, errors.New("report identity or timestamp mismatch")
	}
	desired, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
	if err != nil {
		return nil, err
	}
	if !exists || report.Generation != desired.Generation || report.Digest != desired.Digest {
		return nil, errors.New("report target is not current")
	}
	if err := validateManagedReportForDesired(report, desired); err != nil {
		return nil, err
	}
	key := reportKey(c.cell, req.Node, report.Role)
	for range 8 {
		current, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
		if err != nil || !exists || !sameJSON(current, desired) {
			return nil, errors.New("desired changed before report commit")
		}
		if _, _, err := c.authorize(ctx, req); err != nil {
			return nil, err
		}
		var old Report
		revision, exists, err := c.get(ctx, key, &old)
		if err != nil {
			return nil, err
		}
		if exists {
			if report.Generation < old.Generation || report.Generation == old.Generation && report.ObservedAt.Before(old.ObservedAt) {
				return nil, errors.New("report ordering moved backward")
			}
			if report.Generation == old.Generation && report.ObservedAt.Equal(old.ObservedAt) && !sameJSON(report, old) {
				return nil, errors.New("report timestamp collision")
			}
		}
		_, err = c.cas(ctx, key, report, revision)
		if err == nil {
			current, _, exists, checkErr := c.readDesired(ctx, req.Node, report.Role)
			if checkErr != nil || !exists || !sameJSON(current, desired) {
				return nil, errors.New("desired changed during report commit")
			}
			return struct {
				Accepted bool `json:"accepted"`
			}{true}, nil
		}
		if !casConflict(err) {
			return nil, fmt.Errorf("store report: %w", err)
		}
	}
	return nil, errors.New("report contention")
}

func validateManagedReportForDesired(report Report, desired Desired) error {
	if desired.ManagedMember == nil {
		if report.Managed != nil {
			return errors.New("generic desired cannot accept a managed process report")
		}
		return nil
	}
	if report.State != "running" {
		if report.Managed != nil {
			return errors.New("nonrunning managed report cannot carry process proof")
		}
		return nil
	}
	launch, observation := desired.ManagedMember, report.Managed
	if launch.Runtime == nil || observation == nil || observation.Member != launch.Member ||
		observation.Authority != launch.Authority || observation.OCI != launch.OCI ||
		observation.VolumeID != launch.VolumeID || observation.AttachmentID != launch.AttachmentID ||
		observation.AttachmentETag != launch.AttachmentETag ||
		observation.FileSystemUUID != launch.Runtime.FileSystemUUID ||
		observation.FileSystemType != launch.Runtime.FileSystemType ||
		observation.MountDevice != launch.Runtime.DevicePath || observation.MountPath != launch.Runtime.MountPath ||
		observation.MountID == 0 || observation.ProcessPID < 2 || observation.ProcessStart == "" ||
		!strings.HasPrefix(observation.ProcessCgroup, "/") || !lowerHex(observation.ProcessBootID, 32) ||
		!observation.StorageRecovered || !observation.ListenerReady {
		return errors.New("managed report lacks exact mounted process identity")
	}
	if observation.Container != nil && (!observation.Container.valid() ||
		observation.Container.HostPID != observation.ProcessPID || observation.Container.KernelStart != observation.ProcessStart ||
		observation.Container.Cgroup != observation.ProcessCgroup || observation.Container.MountID != observation.MountID) {
		return errors.New("managed container report differs from its kernel identity")
	}
	if proof := observation.ServingProof; proof != nil {
		if proof.SchemaVersion != 1 || proof.Process.PID != managedReportMemberPID(observation) ||
			proof.Process.StartNonce != observation.ProcessBootID ||
			proof.Scope != (memberstatus.Scope{
				ClusterID: launch.Member.Scope.ClusterID, TenantID: launch.Member.Scope.TenantID,
				DatabaseID: launch.Member.Scope.DatabaseID, ShardID: launch.Member.Scope.ShardID,
				MemberID: launch.Member.Scope.MemberID, Incarnation: launch.Member.Scope.Incarnation,
			}) || proof.Authority != (memberstatus.Authority{
			Epoch: launch.Authority.Epoch, ConfigurationID: launch.Authority.ConfigurationID,
			CertificateSHA256: launch.Authority.CertificateSHA256, TLSLeafSHA256: launch.Authority.TLSLeafSHA256,
		}) || !proof.Serving || !proof.Listeners.Client || !proof.Listeners.Replication ||
			proof.Replication.PeerMemberID != launch.Runtime.ReplicationPeerMemberID {
			return errors.New("managed serving proof differs from the desired process or signed member")
		}
	}
	return nil
}

