func ensureManagedMemberLayout(root string, launch ManagedMemberLaunch, identity WorkloadIdentity) (managedRuntimePaths, error) {
	paths, err := runtimePaths(root, launch)
	if err != nil {
		return managedRuntimePaths{}, err
	}
	if err := verifyManagedDirectory(root, identity, 0750); err != nil {
		return managedRuntimePaths{}, err
	}
	for _, entry := range []struct {
		path string
		mode os.FileMode
	}{{paths.memberDir, 0750}, {paths.material, 0750}, {filepath.Dir(paths.socket), 0730}} {
		if err := os.Mkdir(entry.path, 0700); err == nil {
			if err := os.Chown(entry.path, 0, int(identity.GID)); err != nil {
				return managedRuntimePaths{}, err
			}
			if err := os.Chmod(entry.path, entry.mode); err != nil {
				return managedRuntimePaths{}, err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return managedRuntimePaths{}, err
		}
		if err := verifyManagedDirectory(entry.path, identity, entry.mode); err != nil {
			return managedRuntimePaths{}, err
		}
	}
	return paths, nil
}

func runtimePaths(root string, launch ManagedMemberLaunch) (managedRuntimePaths, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/" {
		return managedRuntimePaths{}, errors.New("managed runtime root must be a clean absolute directory")
	}
	scope := launch.Member.Scope
	if err := validateManagedMemberBinding(launch.Member); err != nil {
		return managedRuntimePaths{}, err
	}
	sum := sha256.Sum256([]byte(scope.ClusterID + "/" + scope.TenantID + "/" + scope.DatabaseID + "/" +
		strconv.FormatUint(scope.ShardID, 10) + "/" + scope.MemberID + "/" + scope.Incarnation + "/" +
		strconv.FormatUint(launch.Member.HostAttempt, 10)))
	memberDir := filepath.Join(root, hex.EncodeToString(sum[:16]))
	paths := managedRuntimePaths{
		memberDir:  memberDir,
		mount:      filepath.Join(memberDir, "volume"),
		material:   filepath.Join(memberDir, "material"),
		socket:     filepath.Join(memberDir, "control", "member.sock"),
		nativeRoot: filepath.Join(memberDir, "native-root.sock"),
	}
	if len(paths.socket) >= 108 || len(paths.nativeRoot) >= 108 {
		return managedRuntimePaths{}, errors.New("managed socket path exceeds Unix limit")
	}
	return paths, nil
}

func verifyManagedDirectory(path string, identity WorkloadIdentity, mode os.FileMode) error {
	if err := inspectWorkloadPath(filepath.Dir(path), identity, true, false, true); err != nil {
		return err
	}
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != 0 || owner.Gid != identity.GID || info.Mode().Perm() != mode {
		return fmt.Errorf("unsafe managed runtime directory %s", path)
	}
	return nil
}

func validateManagedMemberBinding(binding ManagedMemberBinding) error {
	scope := binding.Scope
	if !lowerHexIdentity(scope.ClusterID) || !lowerHexIdentity(scope.Incarnation) ||
		!canonicalMemberID(scope.TenantID) || !canonicalMemberID(scope.DatabaseID) ||
		!canonicalMemberID(scope.MemberID) || scope.ShardID == 0 || binding.HostAttempt == 0 {
		return errors.New("managed member identity is invalid")
	}
	return nil
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

native_pin.text:
func (a *Agent) pinManagedNativeRootDesired(role, fingerprint string) error {
	_, deadline, err := a.executionLease()
	if err != nil {
		return err
	}
	a.nativeRootMu.Lock()
	if a.nativeDesired == nil {
		a.nativeDesired = make(map[string]nativeRootDesired)
	}
	a.nativeDesired[role] = nativeRootDesired{fingerprint: fingerprint, until: deadline}
	a.nativeRootMu.Unlock()
	return nil
}

func (a *Agent) extendManagedNativeRootPin(role, fingerprint string) error {
	_, deadline, err := a.executionLease()
	if err != nil {
		return err
	}
	a.nativeRootMu.Lock()
	defer a.nativeRootMu.Unlock()
	if pin, pinned := a.nativeDesired[role]; pinned && pin.fingerprint == fingerprint && deadline.After(pin.until) {
		a.nativeDesired[role] = nativeRootDesired{fingerprint: fingerprint, until: deadline}
	}
	return nil
}

func (a *Agent) revokeManagedNativeRoot(role string) error {
	a.nativeRootMu.Lock()
	delete(a.nativeDesired, role)
	a.nativeRootMu.Unlock()
	return a.stopManagedNativeRoot(role)
}

func (a *Agent) nativeRootDesiredDeadline(role, fingerprint string) (time.Time, error) {
	a.nativeRootMu.Lock()
	pin, found := a.nativeDesired[role]
	a.nativeRootMu.Unlock()
	if !found || pin.fingerprint != fingerprint || !time.Now().Before(pin.until) {
		return time.Time{}, errors.New("managed native OCI root desired pin expired or changed")
	}
	return pin.until, nil
}

func (a *Agent) authorizeManagedNativeRoot(ctx context.Context, peer nativerootoci.Peer,
	desired Desired, root *managedNativeRoot,
) (time.Time, error) {
	if ctx.Err() != nil || a.sessionLost.Load() {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "session_revoked",
			Err: errors.New("managed native OCI root peer is unauthorized")}
	}
	if peer.UID != a.cfg.WorkloadIdentity.UID || peer.GID != a.cfg.WorkloadIdentity.GID || peer.PID <= 0 {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "peer_credentials",
			Err: errors.New("managed native OCI root peer is unauthorized")}
	}
	a.nativeRootMu.Lock()
	active := a.nativeRoots[desired.Role] == root
	pin, pinned := a.nativeDesired[desired.Role]
	a.nativeRootMu.Unlock()
	if !active || !pinned || pin.fingerprint != root.fingerprint || !time.Now().Before(pin.until) {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "listener_or_pin_revoked",
			Err: errors.New("managed native OCI root listener is no longer active")}
	}
	_, deadline, err := a.executionLease()
	if err != nil {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "execution_lease", Err: err}
	}
	if pin.until.Before(deadline) {
		deadline = pin.until
	}
	observed, err := a.runner.Observe(ctx, desired.Role)
	if err != nil || !observed.Running {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "process_unavailable",
			Err: errors.New("managed native OCI root peer differs from active member")}
	}
	if observed.PID != peer.PID ||
		observed.Digest != desired.Digest || observed.Fingerprint != root.fingerprint ||
		observed.CgroupMemoryMaxBytes != desired.ManagedMember.CgroupMemoryMaxBytes {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "process_witness",
			Err: errors.New("managed native OCI root peer differs from active member")}
	}
	runner, ok := a.runner.(*processRunner)
	if !ok || runner.cgroups == "" {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "cgroup_witness",
			Err: errors.New("managed native OCI root has no native cgroup witness")}
	}
	contained, err := nativeCgroupContainsPID(filepath.Join(runner.cgroups, desired.Role), peer.PID)
	if err != nil || !contained {
		return time.Time{}, nativerootoci.AuthorizationError{Cause: "cgroup_membership",
			Err: errors.New("managed native OCI root peer left its role cgroup")}
	}
	return deadline, nil
}

func (a *Agent) executionLease() (session, time.Time, error) {
	if err := a.checkClock(); err != nil {
		return session{}, time.Time{}, err
	}
	a.mu.RLock()
	s, deadline := a.session, a.sessionSafeUntil
	a.mu.RUnlock()
	if deadline.IsZero() || !time.Now().Before(deadline) || !sessionUsableUntil(s, a.wallTime()) {
		return session{}, time.Time{}, errSessionExecutionReserve
	}
	return s, deadline, nil
}

