func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func validateManagedMemberLaunch(launch ManagedMemberLaunch, d Desired, r Registration) error {
	if len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
		return errors.New("managed desired cannot carry arbitrary arguments or environment")
	}
	if validateDigest(launch.SourceDigest) != nil ||
		!strings.HasPrefix(launch.VolumeID, "ocid1.volume.") ||
		!strings.HasPrefix(launch.AttachmentID, "ocid1.volumeattachment.") ||
		len(launch.VolumeID) > 255 || len(launch.AttachmentID) > 255 ||
		strings.ContainsFunc(launch.VolumeID, unicode.IsSpace) || strings.ContainsFunc(launch.AttachmentID, unicode.IsSpace) ||
		launch.Authority.Epoch == 0 ||
		!lowerHex(launch.Authority.ConfigurationID, 64) ||
		!lowerHex(launch.Authority.CertificateSHA256, 64) ||
		!lowerHex(launch.Authority.TLSLeafSHA256, 64) {
		return errors.New("managed launch source, volume or authority is invalid")
	}
	if d.Withdrawn {
		if launch.ProcessMemoryBytes != 0 || launch.MemoryHeadroomBytes != 0 || launch.CgroupMemoryMaxBytes != 0 || launch.SystemReserveBytes != 0 || launch.Runtime != nil {
			return errors.New("withdrawn managed desired contains memory execution data")
		}
		return nil
	}
	const gib = uint64(1 << 30)
	p, h, c := launch.ProcessMemoryBytes, launch.MemoryHeadroomBytes, launch.CgroupMemoryMaxBytes
	if p < 4*gib || h < max(gib, p/4) || h >= p || launch.SystemReserveBytes == 0 ||
		launch.SystemReserveBytes > math.MaxInt64 || launch.SystemReserveBytes != uint64(r.SystemReserveBytes) ||
		validateCgroupMemoryMax(c) != nil || c < p || c > uint64(r.Capacity.MemoryBytes) ||
		p > math.MaxInt64 || h > math.MaxInt64 || p%uint64(os.Getpagesize()) != 0 || h%uint64(os.Getpagesize()) != 0 {
		return errors.New("managed process memory, headroom or cgroup cap is invalid")
	}
	if launch.Runtime != nil {
		if launch.AttachmentETag == "" {
			return errors.New("managed runtime requires an exact attachment ETag")
		}
		if err := validateManagedRuntimePins(*launch.Runtime); err != nil {
			return err
		}
	}
	return nil
}

func validateManagedRuntimePins(pins ManagedRuntimePins) error {
	if !strings.HasPrefix(pins.DevicePath, "/dev/") || filepath.Clean(pins.DevicePath) != pins.DevicePath ||
		!filepath.IsAbs(pins.MountPath) || filepath.Clean(pins.MountPath) != pins.MountPath ||
		!filesystemUUIDPattern.MatchString(pins.FileSystemUUID) ||
		pins.FileSystemType != "ext4" && pins.FileSystemType != "xfs" ||
		!lowerHex(pins.TrustedKeySHA256, 64) || !lowerHex(pins.ServerCertificateSHA256, 64) ||
		!lowerHex(pins.ServerPrivateKeySHA256, 64) || !lowerHex(pins.ClientCARootsSHA256, 64) ||
		!lowerHex(pins.ClientManagedMaterialManifestSHA256, 64) ||
		!lowerHex(pins.LiveS3ConfigSHA256, 64) || !lowerHex(pins.LiveS3TargetSHA256, 64) ||
		pins.SQLSchemaBundleSHA256 != "" && !lowerHex(pins.SQLSchemaBundleSHA256, 64) ||
		pins.LiveS3Credential.Validate() != nil ||
		!validPrivateIPv4Endpoint(pins.ReplicationListenAddress) {
		return errors.New("managed runtime device, filesystem, material or listener pin is invalid")
	}
	peer := pins.ReplicationPeerMemberID != "" || pins.ReplicationPeerAddress != "" || pins.ReplicationServerCASHA256 != ""
	if !peer || !canonicalMemberID(pins.ReplicationPeerMemberID) || !validPrivateIPv4Endpoint(pins.ReplicationPeerAddress) ||
		!lowerHex(pins.ReplicationServerCASHA256, 64) {
		return errors.New("managed runtime outbound peer pins are incomplete")
	}
	if pins.BackupManifestSHA256 != "" {
		if !lowerHex(pins.BackupManifestSHA256, 64) || !lowerHex(pins.BackupS3ConfigSHA256, 64) ||
			!lowerHex(pins.BackupS3TargetSHA256, 64) || !lowerHex(pins.BackupS3CredentialSHA256, 64) ||
			!lowerHex(pins.BackupDataKeySHA256, 64) || pins.BackupS3TargetSHA256 == pins.LiveS3TargetSHA256 ||
			pins.BackupOwner && (pins.BackupS3Credential.Validate() != nil || pins.BackupDataKey.Validate() != nil ||
				pins.BackupS3Credential.SecretOCID == pins.LiveS3Credential.SecretOCID ||
				pins.BackupS3Credential.SecretOCID == pins.BackupDataKey.SecretOCID) ||
			!pins.BackupOwner && (pins.BackupS3Credential != (oci.SecretVersionReference{}) ||
				pins.BackupDataKey != (oci.SecretVersionReference{})) {
			return errors.New("managed backup runtime pins are incomplete")
		}
	} else if pins.BackupS3ConfigSHA256 != "" || pins.BackupS3TargetSHA256 != "" ||
		pins.BackupS3CredentialSHA256 != "" || pins.BackupDataKeySHA256 != "" || pins.BackupOwner ||
		pins.BackupS3Credential != (oci.SecretVersionReference{}) || pins.BackupDataKey != (oci.SecretVersionReference{}) {
		return errors.New("partial managed backup runtime pins")
	}
	return nil
}

func (c *Controller) serveMaterial(ctx context.Context, req request, registration Registration, session session) (any, error) {
	if c.materialProvider == nil || c.managedVerifier == nil || registration.ManagedMember == nil ||
		registration.ManagedOCI == nil || registration.ManagedPlacement == nil ||
		registration.Generation != session.RegistrationGeneration {
		return nil, errors.New("managed material delivery is unavailable")
	}
	var query materialQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(managedHostFileNames[:], query.File) && query.File != managedCredentialFileName || query.Role == "" ||
		query.Length < 1 || query.Length > materialChunkBytes || query.Offset < 0 ||
		query.Offset >= maxManagedHostFileBytes || len(query.EphemeralPublicKey) != 32 ||
		query.RegistrationGeneration != registration.Generation ||
		query.MemberID != registration.ManagedMember.Scope.MemberID ||
		query.HostAttempt != registration.ManagedMember.HostAttempt ||
		query.InstanceID != registration.ManagedOCI.InstanceID {
		return nil, errors.New("managed material query differs from current host registration")
	}
	desired, _, exists, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil {
		return nil, err
	}
	if !exists || desired.Withdrawn || desired.ManagedMember == nil ||
		desired.Generation != query.DesiredGeneration ||
		desired.ManagedMember.Member != *registration.ManagedMember ||
		desired.ManagedMember.OCI != *registration.ManagedOCI ||
		validateDesired(desired, c.cell, registration) != nil {
		return nil, errors.New("managed material is not current desired for this host")
	}
	if slices.Contains(managedHostFileNames[:], query.File) && !managedHostFileEnabled(desired, query.File) {
		return nil, errors.New("managed material file is not enabled by signed desired")
	}
	if slices.Contains(managedHostFileNames[:], query.File) && query.Offset >= managedHostFileLimit(query.File) {
		return nil, errors.New("managed material chunk offset exceeds its file limit")
	}
	fingerprint, err := desiredFingerprint(desired)
	if err != nil || fingerprint != query.DesiredFingerprint {
		return nil, errors.New("managed material desired fingerprint changed")
	}
	if err := c.managedVerifier.VerifyManagedRegistration(ctx, registration); err != nil {
		return nil, err
	}
	files, err := c.materialProvider(ctx, desired, registration)
	if err != nil {
		return nil, err
	}
	contents := files[query.File]
	if len(contents) == 0 || len(contents) > managedHostFileLimit(query.File) || query.Offset >= len(contents) {
		return nil, errors.New("managed material file is missing or oversized")
	}
	end := min(len(contents), query.Offset+query.Length)
	return encryptMaterialChunk(req, query, contents[query.Offset:end], len(contents), contents)
}

func (a *Agent) fetchManagedMaterial(ctx context.Context, desired Desired, registration Registration) error {
	if desired.ManagedMember == nil || registration.ManagedMember == nil ||
		desired.ManagedMember.Member != *registration.ManagedMember || a.cfg.ManagedRuntimeRoot == "" {
		return errors.New("managed material delivery lacks exact host binding")
	}
	paths, err := ensureManagedMemberLayout(a.cfg.ManagedRuntimeRoot, *desired.ManagedMember, a.cfg.WorkloadIdentity)
	if err != nil {
		return err
	}
	fingerprint, err := desiredFingerprint(desired)
	if err != nil {
		return err
	}
	for _, name := range managedHostFilesFor(desired) {
		contents, digest, err := a.downloadManagedFile(ctx, desired, registration, fingerprint, name)
		if err != nil {
			return fmt.Errorf("retrieve managed material %s: %w", name, err)
		}
		if want := expectedHostMaterialDigest(desired, name); want != "" && digest != want {
			return fmt.Errorf("managed material %s differs from signed desired", name)
		}
		if err := installManagedFile(paths.material, name, contents, digest, a.cfg.WorkloadIdentity); err != nil {
			return fmt.Errorf("install managed material %s: %w", name, err)
		}
	}
	return nil
}

func (a *Agent) downloadManagedFile(ctx context.Context, desired Desired, registration Registration,
	fingerprint, name string,
) ([]byte, string, error) {
	var contents []byte
	var digest string
	total := 0
	for total == 0 || len(contents) < total {
		private, err := ecdh.X25519().GenerateKey(rand.Reader)
		if err != nil {
			return nil, "", err
		}
		query := materialQuery{Role: desired.Role, File: name, DesiredGeneration: desired.Generation,
			DesiredFingerprint: fingerprint, MemberID: desired.ManagedMember.Member.Scope.MemberID,
			HostAttempt:            desired.ManagedMember.Member.HostAttempt,
			RegistrationGeneration: registration.Generation,
			InstanceID:             desired.ManagedMember.OCI.InstanceID, Offset: len(contents), Length: materialChunkBytes,
			EphemeralPublicKey: private.PublicKey().Bytes()}
		var reply materialReply
		req, err := a.sendToLeader(ctx, "material", query, &reply, nil, nil)
		if err != nil {
			return nil, "", err

func (a *Agent) reconcileManaged(ctx context.Context, d Desired, target desiredReply,
	backupPending bool,
) (resultErr error) {
	// Load telemetry belongs to the process this pass verifies: forget the
	// previous block now, so a member this pass stops, fails or replaces
	// never keeps publishing its predecessor's load. A successful status
	// report records the new block.
	a.noteTerraBaseLoad(d.Role, nil)
	defer func() {
		if resultErr != nil {
			resultErr = errors.Join(resultErr, a.stopManagedNativeRoot(d.Role))
		}
	}()
	launch := d.ManagedMember
	current, err := a.runner.Observe(ctx, d.Role)
	if err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	if current.Running && current.CgroupMemoryMaxBytes != launch.CgroupMemoryMaxBytes {
		return errors.Join(errors.New("managed role memory.max drifted from desired cap"), a.runner.Stop(ctx, d.Role))
	}
	if launch.Runtime == nil || a.cfg.ManagedRuntimeRoot == "" {
		return errors.Join(errors.New("managed member launch awaits verified mount, artifact, authority material and member identity"), a.runner.Stop(ctx, d.Role))
	}
	if target.Registration == nil || target.Registration.SystemReserveBytes <= 0 ||
		a.cfg.BakedSystemReserveBytes == 0 ||
		launch.SystemReserveBytes != a.cfg.BakedSystemReserveBytes ||
		uint64(target.Registration.SystemReserveBytes) != a.cfg.BakedSystemReserveBytes {
		return errors.Join(errors.New("managed system reserve differs from image priority profile"), a.runner.Stop(ctx, d.Role))
	}
	check := a.memoryCheck
	if check == nil {
		check = validateManagedHostMemory
	}
	if err := check(*target.Registration); err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	fingerprint, err := desiredFingerprint(d)
	if err != nil {
		return err
	}
	if err := a.stopManagedNativeRootIfChanged(d.Role, fingerprint); err != nil {
		return err
	}
	executable, err := a.fetchArtifact(ctx, d.Role, d.Digest)
	if err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	if err := a.fetchManagedMaterial(ctx, d, *target.Registration); err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	previousCredentialGeneration, credentialGeneration, credentialChanged, err := a.fetchManagedCredentials(ctx, d, *target.Registration)
	if err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	reloadCredentials := current.Running && credentialChanged && previousCredentialGeneration >= 2
	if current.Running && credentialChanged && credentialGeneration > 1 && !reloadCredentials {
		if err := a.runner.Stop(ctx, d.Role); err != nil {
			return err
		}
		current.Running = false
	}
	if err := a.ensureManagedVolume(ctx, d, target); err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	_, mount, socket, err := prepareManagedRuntime(ctx, a.cfg, d, "", "")
	if err != nil {
		return errors.Join(err, a.runner.Stop(ctx, d.Role))
	}
	defer mount.close()

func prepareManagedRuntime(ctx context.Context, cfg AgentConfig, d Desired, executable, fingerprint string) (Workload, managedMount, string, error) {
	launch := d.ManagedMember
	if launch == nil || launch.Runtime == nil || cfg.ManagedRuntimeRoot == "" {
		return Workload{}, managedMount{}, "", errors.New("managed member launch awaits verified mount, artifact, authority material and member identity")
	}
	if err := ctx.Err(); err != nil {
		return Workload{}, managedMount{}, "", err
	}
	paths, err := runtimePaths(cfg.ManagedRuntimeRoot, *launch)
	if err != nil {
		return Workload{}, managedMount{}, "", err
	}
	if paths.mount != launch.Runtime.MountPath {
		return Workload{}, managedMount{}, "", errors.New("managed mount path differs from signed desired")
	}
	identity := cfg.WorkloadIdentity
	if err := verifyManagedDirectory(cfg.ManagedRuntimeRoot, identity, 0750); err != nil {
		return Workload{}, managedMount{}, "", err
	}
	if err := verifyManagedDirectory(paths.material, identity, 0750); err != nil {
		return Workload{}, managedMount{}, "", err
	}
	if err := verifyManagedDirectory(filepath.Dir(paths.socket), identity, 0730); err != nil {
		return Workload{}, managedMount{}, "", err
	}
	mount, err := verifyManagedMount(paths, *launch.Runtime, identity)
	if err != nil {
		return Workload{}, managedMount{}, "", err
	}
	keepMount := false
	defer func() {
		if !keepMount {
			mount.close()
		}
	}()
	files := []struct {
		name, digest string
		maximum      int64
	}{
		{"authority.tbca", launch.Authority.CertificateSHA256, 1 << 20},
		{"trusted-public-key", launch.Runtime.TrustedKeySHA256, 32},
		{"server.crt", launch.Runtime.ServerCertificateSHA256, 1 << 20},
		{"server.key", launch.Runtime.ServerPrivateKeySHA256, 1 << 20},
		{"client-ca.pem", launch.Runtime.ClientCARootsSHA256, 1 << 20},
		{"signed-v2-s3-config.json", launch.Runtime.LiveS3ConfigSHA256, 16 << 10},
	}
	contents := make(map[string][]byte, len(files))
	for _, item := range files {
		contents[item.name], err = verifyManagedMaterial(filepath.Join(paths.material, item.name), item.digest, identity, item.maximum)
		if err != nil {
			return Workload{}, managedMount{}, "", err
		}
	}
	if len(contents["trusted-public-key"]) != 32 {
		return Workload{}, managedMount{}, "", errors.New("authority trust key has wrong length")
	}
	_, nativeRoot, err := nativeRootTarget(*launch, contents["signed-v2-s3-config.json"])
	if err != nil {
		return Workload{}, managedMount{}, "", err
	}
	chain, err := tls.X509KeyPair(contents["server.crt"], contents["server.key"])
	if err != nil || len(chain.Certificate) == 0 {
		return Workload{}, managedMount{}, "", errors.New("member TLS leaf and private key do not match")
	}
	leaf := sha256.Sum256(chain.Certificate[0])
	if hex.EncodeToString(leaf[:]) != launch.Authority.TLSLeafSHA256 {
		return Workload{}, managedMount{}, "", errors.New("member TLS leaf differs from signed authority pin")
	}
	if pool := x509.NewCertPool(); !pool.AppendCertsFromPEM(contents["client-ca.pem"]) {
		return Workload{}, managedMount{}, "", errors.New("member client CA roots are invalid")
	}
	clientArgs, err := readManagedClientMaterial(paths.material,
		launch.Runtime.ClientManagedMaterialManifestSHA256, launch.Runtime.SQLSchemaBundleSHA256,
		launch.Runtime.ReplicationListenAddress, identity, 0)
	if err != nil {
		return Workload{}, managedMount{}, "", fmt.Errorf("managed client HTTPS material: %w", err)
	}
	if _, err := readManagedBackupMaterial(paths.material, *launch, contents["trusted-public-key"],
		contents["signed-v2-s3-config.json"], identity, 0, false); err != nil {
		return Workload{}, managedMount{}, "", fmt.Errorf("managed backup material: %w", err)
	}

func newManagedMemberFirecrackerS3CredentialResolver(reference oci.SecretVersionReference) (*managedMemberFirecrackerS3CredentialResolver, error) {
	expected := oci.SecretVersionReference{
		SecretOCID: managedMemberFirecrackerS3SecretOCID, VersionNumber: managedMemberFirecrackerS3SecretVersion,
	}
	if reference != expected {
		return nil, errors.New("guest S3 credential reference differs from exporter fixture pin")
	}
	accessKeyPath, accessKeyOK := os.LookupEnv(managedMemberFirecrackerS3AccessKeyEnv)
	secretKeyPath, secretKeyOK := os.LookupEnv(managedMemberFirecrackerS3SecretKeyEnv)
	if !accessKeyOK || !secretKeyOK || accessKeyPath != managedMemberFirecrackerS3AccessKeyPath ||
		secretKeyPath != managedMemberFirecrackerS3SecretKeyPath {
		return nil, errors.New("private guest S3 credential file paths are unavailable")
	}
	return &managedMemberFirecrackerS3CredentialResolver{
		reference: expected, accessKeyIDPath: accessKeyPath, secretAccessPath: secretKeyPath,
	}, nil
}

func (resolver *managedMemberFirecrackerS3CredentialResolver) Resolve(ctx context.Context, reference oci.SecretVersionReference) (ManagedS3Credentials, error) {
	if resolver == nil || ctx == nil || ctx.Err() != nil || reference != resolver.reference {
		return ManagedS3Credentials{}, errors.New("guest S3 credential reference is invalid")
	}
	accessKeyID, err := readManagedMemberFirecrackerS3Credential(resolver.accessKeyIDPath)
	if err != nil {
		return ManagedS3Credentials{}, errors.New("private guest S3 access key is unavailable")
	}
	defer clear(accessKeyID)
	secretAccessKey, err := readManagedMemberFirecrackerS3Credential(resolver.secretAccessPath)
	if err != nil {
		return ManagedS3Credentials{}, errors.New("private guest S3 secret key is unavailable")
	}
	defer clear(secretAccessKey)
	if err := ctx.Err(); err != nil {
		return ManagedS3Credentials{}, errors.New("guest S3 credential resolution was canceled")
	}
	return ManagedS3Credentials{AccessKeyID: string(accessKeyID), SecretAccessKey: string(secretAccessKey)}, nil
}

func readManagedMemberFirecrackerS3Credential(path string) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, errors.New("private credential file could not be opened")
	}
	file := os.NewFile(uintptr(fd), "managed S3 credential")
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, errors.New("private credential file could not be inspected")
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || owner.Uid != 0 || info.Mode().Perm() != 0600 ||
		info.Size() <= 0 || info.Size() > managedMemberFirecrackerS3CredentialMaxSize {
		return nil, errors.New("private credential file has unsafe ownership, mode or size")
	}
	contents, err := io.ReadAll(io.LimitReader(file, managedMemberFirecrackerS3CredentialMaxSize+1))
	if err != nil || len(contents) == 0 || len(contents) > managedMemberFirecrackerS3CredentialMaxSize ||
		!validS3Credential(string(contents)) {
		clear(contents)
		return nil, errors.New("private credential file content is invalid")
	}
	return contents, nil

func managedMemberCurrentEvidence(ctx context.Context, controller *Controller, desired Desired, paths managedRuntimePaths, initial Report) (managedMemberFirecrackerEvidence, error) {
	hosts, err := controller.ListHosts(ctx)
	if err != nil {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("read accepted host report: %w", err)
	}
	if len(hosts) != 1 || !hosts[0].Verified || len(hosts[0].Reports) != 1 {
		return managedMemberFirecrackerEvidence{}, errors.New("accepted host report is absent")
	}
	report := hosts[0].Reports[0]
	if report.State != "running" || report.Managed == nil || report.Digest != desired.Digest ||
		report.Managed.ProcessPID != initial.Managed.ProcessPID ||
		report.Managed.Member != desired.ManagedMember.Member ||
		report.Managed.Authority != desired.ManagedMember.Authority ||
		report.Managed.FileSystemUUID != desired.ManagedMember.Runtime.FileSystemUUID ||
		report.Managed.MountPath != paths.mount || !report.Managed.StorageRecovered || !report.Managed.ListenerReady {
		return managedMemberFirecrackerEvidence{}, errors.New("accepted managed report changed identity or lost readiness")
	}
	pid := report.Managed.ProcessPID
	status, err := os.ReadFile(fmt.Sprintf("/proc/%d/status", pid))
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	uid, gid, err := managedMemberProcessIdentity(string(status))
	if err != nil {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("read native UID/GID: %w", err)
	}
	if uid != 65534 || gid != 65534 {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("native process UID/GID = %d/%d", uid, gid)
	}
	_, mount, socket, err := prepareManagedRuntime(ctx, AgentConfig{
		ManagedRuntimeRoot: "/srv/ts-managed", WorkloadIdentity: WorkloadIdentity{UID: 65534, GID: 65534},
	}, desired, "", "")
	if err != nil {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("recheck pinned native mount/material: %w", err)
	}
	defer mount.close()
	if mount.id != report.Managed.MountID || socket != paths.socket {
		return managedMemberFirecrackerEvidence{}, errors.New("reported mount or member socket differs from held native witness")
	}
	authority, err := verifyManagedMaterial(filepath.Join(paths.material, "authority.tbca"),
		desired.ManagedMember.Authority.CertificateSHA256, WorkloadIdentity{UID: 65534, GID: 65534}, 1<<20)
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	if err := inspectManagedVolumeClaim(paths, *desired.ManagedMember, WorkloadIdentity{UID: 65534, GID: 65534}, mount, authority); err != nil {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("recheck exact recovered claim: %w", err)
	}
	cgroupPath := filepath.Join("/sys/fs/cgroup", strings.TrimPrefix(report.Managed.ProcessCgroup, "/"))
	memoryBytes, err := os.ReadFile(filepath.Join(cgroupPath, "memory.max"))
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	limit, err := strconv.ParseUint(strings.TrimSpace(string(memoryBytes)), 10, 64)
	if err != nil || limit != desired.ManagedMember.CgroupMemoryMaxBytes {
		return managedMemberFirecrackerEvidence{}, errors.New("native memory.max differs from signed cap")
	}
	procs, err := os.ReadFile(filepath.Join(cgroupPath, "cgroup.procs"))
	if err != nil || !strings.Contains("\n"+string(procs), fmt.Sprintf("\n%d\n", pid)) {
		return managedMemberFirecrackerEvidence{}, errors.New("reported process is absent from native role cgroup")
	}
	claimPath := filepath.Join(paths.mount, managedVolumeClaimName)
	claim, err := os.ReadFile(claimPath)
	if err != nil || string(claim) != string(managedVolumeClaimBytes(*desired.ManagedMember)) {
		return managedMemberFirecrackerEvidence{}, errors.New("durable volume claim differs from signed member")
	}
	claimInfo, err := os.Lstat(claimPath)
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	claimOwner, ok := claimInfo.Sys().(*syscall.Stat_t)
	if !ok || !claimInfo.Mode().IsRegular() || claimOwner.Uid != 0 || claimOwner.Gid != 0 || claimInfo.Mode().Perm() != 0600 {
		return managedMemberFirecrackerEvidence{}, errors.New("durable claim ownership or mode is unsafe")
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:9464/metrics", nil)
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	client := &http.Client{Timeout: 3 * time.Second}
	response, err := client.Do(request)
	if err != nil {
		return managedMemberFirecrackerEvidence{}, err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return managedMemberFirecrackerEvidence{}, fmt.Errorf("native metrics HTTP %d", response.StatusCode)
	}
	metricsBytes, err := io.ReadAll(io.LimitReader(response.Body, 256<<10+1))
	if err != nil || len(metricsBytes) > 256<<10 {
		return managedMemberFirecrackerEvidence{}, errors.New("native metrics exceeded bound")
	}
	metrics := make(map[string]float64)
	for line := range strings.SplitSeq(string(metricsBytes), "\n") {
		for _, name := range []string{"terrabase_replication_acks_total", "terrabase_replication_sender_connected", "terrabase_replication_sender_durable_lag_events", "terrabase_replication_sender_applied_lag_events"} {
			if !strings.HasPrefix(line, name) || len(line) <= len(name) || line[len(name)] != ' ' && line[len(name)] != '{' {
				continue
			}
			parts := strings.Fields(line)
			if len(parts) != 2 {
				return managedMemberFirecrackerEvidence{}, errors.New("selected native metric is malformed")
			}
			value, parseErr := strconv.ParseFloat(parts[1], 64)
			if parseErr != nil || math.IsNaN(value) || math.IsInf(value, 0) {
				return managedMemberFirecrackerEvidence{}, errors.New("selected native metric is non-finite")
			}
			if _, exists := metrics[parts[0]]; exists {
				return managedMemberFirecrackerEvidence{}, errors.New("selected native metric is duplicated")
			}
			metrics[parts[0]] = value
		}
	}
	claimDigest := sha256.Sum256(claim)
	return managedMemberFirecrackerEvidence{Version: 1, Node: desired.Node,
		MemberID: desired.ManagedMember.Member.Scope.MemberID, ProcessPID: pid, ProcessUID: uid, ProcessGID: gid,
		ProcessCgroup: report.Managed.ProcessCgroup, MemoryMaxBytes: limit,
		FileSystemUUID: report.Managed.FileSystemUUID, MountID: report.Managed.MountID,
		ClaimSHA256: hex.EncodeToString(claimDigest[:]), StorageRecovered: true, ListenerReady: true,
		Metrics: metrics}, nil
}

mount_table.text:
func exclusiveMountEntry(mountInfoPath, target string, rdev uint64, fsType string, visible uint64) (uint64, error) {
	file, err := os.Open(mountInfoPath)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	device := fmt.Sprintf("%d:%d", unix.Major(rdev), unix.Minor(rdev))
	found := false
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) < 10 || fields[2] != device {
			continue
		}
		separator := -1
		for index := 6; index < len(fields); index++ {
			if fields[index] == "-" {
				separator = index
				break
			}
		}
		if fields[4] != target || fields[3] != "/" || !strings.Contains(","+fields[5]+",", ",rw,") ||
			separator < 0 || separator+1 >= len(fields) || fields[separator+1] != fsType {
			return 0, errors.New("retained filesystem has another or unsafe mount")
		}
		parsed, err := strconv.ParseUint(fields[0], 10, 64)
		if err != nil {
			return 0, err
		}
		found = found || parsed == visible
	}
	if err := scanner.Err(); err != nil {
		return 0, err
	}
	if !found || visible == 0 {
		return 0, errors.New("retained filesystem is not the mount visible at its target")
	}
	return visible, nil
}

